/****************************************************************************
 * app/velaguard_app/src/vg_ui_home.c
 *
 * Issue #01 home UI + Issue #02 live ACQUIRE / detail / Test Read.
 * Design tokens: Dark OLED ops (bg #0F172A, surface #1E293B, accent #22C55E).
 * Identity is display-only. Collector never called from LVGL thread for I/O;
 * UI only reads vg_modbus_snapshot via timer.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#include <lvgl/lvgl.h>

#include "vg_device_id.h"
#include "vg_ui_home.h"

#ifdef CONFIG_VG_ENABLE_MODBUS
#  include "vg_modbus_collector.h"
#endif

/* Design tokens (RGB565-friendly hex) */

#define C_BG         lv_color_hex(0x0F172A)
#define C_SURFACE    lv_color_hex(0x1E293B)
#define C_MUTED      lv_color_hex(0x272F42)
#define C_BORDER     lv_color_hex(0x475569)
#define C_TEXT       lv_color_hex(0xF8FAFC)
#define C_TEXT_DIM   lv_color_hex(0x94A3B8)
#define C_ACCENT     lv_color_hex(0x22C55E)
#define C_DANGER     lv_color_hex(0xEF4444)
#define C_INFO       lv_color_hex(0x38BDF8)
#define C_WARN       lv_color_hex(0xFBBF24)
#define C_CHIP_TEST  lv_color_hex(0x14532D)
#define C_CHIP_PROD  lv_color_hex(0x1E3A5F)

#define SCR_W   480
#define SCR_H   272
#define PAD     6
#define GAP     4
#define HDR_H   32
#define ID_H    36
#define HDR_Y   (PAD / 2)
#define ID_Y    (HDR_Y + HDR_H + GAP)
#define KPI_Y   (ID_Y + ID_H + GAP)
#define KPI_H   78
#define KPI_N   5
#define KPI_W   ((SCR_W - PAD * 2 - GAP * (KPI_N - 1)) / KPI_N)
#define DET_Y   (KPI_Y + KPI_H + GAP)
#define DET_H   (SCR_H - DET_Y - PAD)

#ifdef CONFIG_VG_ENABLE_MODBUS
struct kpi_refs
{
  lv_obj_t *bar;
  lv_obj_t *dot;
  lv_obj_t *value_lbl;
  lv_obj_t *state_lbl;
};

static struct kpi_refs g_acq;
static lv_obj_t *g_detail_labels[3];
static lv_obj_t *g_test_lbl;
static lv_obj_t *g_age_lbl;
#endif

static void style_panel(lv_obj_t *obj, lv_color_t bg, int radius)
{
  lv_obj_set_style_bg_color(obj, bg, 0);
  lv_obj_set_style_bg_opa(obj, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(obj, 1, 0);
  lv_obj_set_style_border_color(obj, C_BORDER, 0);
  lv_obj_set_style_radius(obj, radius, 0);
  lv_obj_set_style_pad_all(obj, 0, 0);
  lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
}

static void make_header(lv_obj_t *parent)
{
  lv_obj_t *hdr;
  lv_obj_t *brand;
  lv_obj_t *sub;
  lv_obj_t *left;
  lv_obj_t *chip;
  lv_obj_t *chip_lbl;
  char chip_txt[24];
  bool prod = vg_is_production_build();

  hdr = lv_obj_create(parent);
  lv_obj_set_size(hdr, SCR_W - PAD * 2, HDR_H);
  lv_obj_set_pos(hdr, PAD, HDR_Y);
  style_panel(hdr, C_SURFACE, 6);
  lv_obj_set_style_pad_hor(hdr, 10, 0);
  lv_obj_set_flex_flow(hdr, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(hdr, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  left = lv_obj_create(hdr);
  lv_obj_set_size(left, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
  lv_obj_set_style_bg_opa(left, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(left, 0, 0);
  lv_obj_set_style_pad_all(left, 0, 0);
  lv_obj_set_flex_flow(left, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(left, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
  lv_obj_set_style_pad_row(left, 0, 0);

  brand = lv_label_create(left);
  lv_label_set_text(brand, "VelaGuard");
  lv_obj_set_style_text_color(brand, C_TEXT, 0);
  lv_obj_set_style_text_font(brand, &lv_font_montserrat_14, 0);

  sub = lv_label_create(left);
  lv_label_set_text(sub, "Edge AI Gateway");
  lv_obj_set_style_text_color(sub, C_TEXT_DIM, 0);
  lv_obj_set_style_text_font(sub, &lv_font_montserrat_10, 0);

  chip = lv_obj_create(hdr);
  lv_obj_set_size(chip, LV_SIZE_CONTENT, 20);
  lv_obj_set_style_bg_color(chip, prod ? C_CHIP_PROD : C_CHIP_TEST, 0);
  lv_obj_set_style_bg_opa(chip, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(chip, 1, 0);
  lv_obj_set_style_border_color(chip, prod ? C_INFO : C_WARN, 0);
  lv_obj_set_style_radius(chip, 10, 0);
  lv_obj_set_style_pad_hor(chip, 8, 0);
  lv_obj_set_style_pad_ver(chip, 1, 0);
  lv_obj_clear_flag(chip, LV_OBJ_FLAG_SCROLLABLE);

  chip_lbl = lv_label_create(chip);
  snprintf(chip_txt, sizeof(chip_txt), "%s",
           prod ? "PRODUCTION" : "TEST");
  lv_label_set_text(chip_lbl, chip_txt);
  lv_obj_set_style_text_color(chip_lbl, prod ? C_INFO : C_WARN, 0);
  lv_obj_set_style_text_font(chip_lbl, &lv_font_montserrat_10, 0);
  lv_obj_center(chip_lbl);
}

static void make_identity(lv_obj_t *parent)
{
  lv_obj_t *row;
  lv_obj_t *id_lbl;
  lv_obj_t *fw_lbl;
  char id_buf[72];
  char fw_buf[40];

  row = lv_obj_create(parent);
  lv_obj_set_size(row, SCR_W - PAD * 2, ID_H);
  lv_obj_set_pos(row, PAD, ID_Y);
  style_panel(row, C_MUTED, 6);
  lv_obj_set_style_pad_hor(row, 10, 0);
  lv_obj_set_style_pad_ver(row, 2, 0);
  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
  lv_obj_set_style_pad_row(row, 1, 0);

  snprintf(id_buf, sizeof(id_buf), "Device  %s", vg_get_device_id());
  id_lbl = lv_label_create(row);
  lv_label_set_text(id_lbl, id_buf);
  lv_label_set_long_mode(id_lbl, LV_LABEL_LONG_DOT);
  lv_obj_set_width(id_lbl, SCR_W - PAD * 2 - 24);
  lv_obj_set_style_text_color(id_lbl, C_TEXT, 0);
  lv_obj_set_style_text_font(id_lbl, &lv_font_montserrat_12, 0);

  snprintf(fw_buf, sizeof(fw_buf), "Firmware  %s", CONFIG_VG_FIRMWARE_VERSION);
  fw_lbl = lv_label_create(row);
  lv_label_set_text(fw_lbl, fw_buf);
  lv_obj_set_style_text_color(fw_lbl, C_TEXT_DIM, 0);
  lv_obj_set_style_text_font(fw_lbl, &lv_font_montserrat_10, 0);
}

static lv_obj_t *make_kpi(lv_obj_t *parent, const char *title,
                          const char *value, const char *state,
                          lv_color_t accent,
#ifdef CONFIG_VG_ENABLE_MODBUS
                          struct kpi_refs *refs
#else
                          void *refs
#endif
                          )
{
  lv_obj_t *card;
  lv_obj_t *bar;
  lv_obj_t *title_lbl;
  lv_obj_t *value_lbl;
  lv_obj_t *state_lbl;
  lv_obj_t *dot;

  (void)refs;

  card = lv_obj_create(parent);
  lv_obj_set_size(card, KPI_W, KPI_H);
  style_panel(card, C_SURFACE, 6);
  lv_obj_set_style_pad_all(card, 0, 0);
  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  bar = lv_obj_create(card);
  lv_obj_set_size(bar, KPI_W, 3);
  lv_obj_set_style_bg_color(bar, accent, 0);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(bar, 0, 0);
  lv_obj_set_style_radius(bar, 0, 0);
  lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);

  title_lbl = lv_label_create(card);
  lv_label_set_text(title_lbl, title);
  lv_obj_set_style_text_color(title_lbl, C_TEXT_DIM, 0);
  lv_obj_set_style_text_font(title_lbl, &lv_font_montserrat_10, 0);
  lv_obj_set_style_pad_top(title_lbl, 4, 0);

  dot = lv_obj_create(card);
  lv_obj_set_size(dot, 10, 10);
  lv_obj_set_style_bg_color(dot, accent, 0);
  lv_obj_set_style_bg_opa(dot, LV_OPA_60, 0);
  lv_obj_set_style_border_width(dot, 2, 0);
  lv_obj_set_style_border_color(dot, accent, 0);
  lv_obj_set_style_radius(dot, 5, 0);
  lv_obj_set_style_pad_all(dot, 0, 0);
  lv_obj_set_style_margin_top(dot, 4, 0);
  lv_obj_clear_flag(dot, LV_OBJ_FLAG_SCROLLABLE);

  value_lbl = lv_label_create(card);
  lv_label_set_text(value_lbl, value);
  lv_label_set_long_mode(value_lbl, LV_LABEL_LONG_DOT);
  lv_obj_set_width(value_lbl, KPI_W - 6);
  lv_obj_set_style_text_align(value_lbl, LV_TEXT_ALIGN_CENTER, 0);
  lv_obj_set_style_text_color(value_lbl, C_TEXT, 0);
  lv_obj_set_style_text_font(value_lbl, &lv_font_montserrat_12, 0);
  lv_obj_set_style_pad_top(value_lbl, 4, 0);

  state_lbl = lv_label_create(card);
  lv_label_set_text(state_lbl, state);
  lv_obj_set_style_text_color(state_lbl, accent, 0);
  lv_obj_set_style_text_font(state_lbl, &lv_font_montserrat_10, 0);
  lv_obj_set_style_pad_top(state_lbl, 2, 0);

#ifdef CONFIG_VG_ENABLE_MODBUS
  if (refs != NULL)
    {
      refs->bar = bar;
      refs->dot = dot;
      refs->value_lbl = value_lbl;
      refs->state_lbl = state_lbl;
    }
#endif

  return card;
}

static void make_kpi_row(lv_obj_t *parent)
{
  lv_obj_t *row;

  row = lv_obj_create(parent);
  lv_obj_set_size(row, SCR_W - PAD * 2, KPI_H);
  lv_obj_set_pos(row, PAD, KPI_Y);
  lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
  lv_obj_set_style_border_width(row, 0, 0);
  lv_obj_set_style_pad_all(row, 0, 0);
  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_column(row, GAP, 0);
  lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

#ifdef CONFIG_VG_ENABLE_MODBUS
  make_kpi(row, "ACQUIRE", "—", "standby", C_ACCENT, &g_acq);
#else
