static const char *quality_text(enum vg_modbus_quality q)
{
  switch (q)
    {
      case VG_MB_Q_GOOD:
        return "good";
      case VG_MB_Q_BAD:
        return "bad";
      case VG_MB_Q_STALE:
        return "stale";
      default:
        return "—";
    }
}

static lv_color_t quality_color(enum vg_modbus_quality q)
{
  switch (q)
    {
      case VG_MB_Q_GOOD:
        return C_ACCENT;
      case VG_MB_Q_BAD:
        return C_DANGER;
      case VG_MB_Q_STALE:
        return C_WARN;
      default:
        return C_TEXT_DIM;
    }
}

