static void refresh_modbus_ui(lv_timer_t *timer)
{
  struct vg_modbus_snapshot snap;
  char vbuf[40];
  char line[96];
  char tline[112];
  lv_color_t col;
  uint8_t i;
  uint32_t now_ms;
  struct timespec ts;

  (void)timer;
  vg_modbus_snapshot_get(&snap);

  clock_gettime(CLOCK_MONOTONIC, &ts);
  now_ms = (uint32_t)((uint64_t)ts.tv_sec * 1000ULL +
                      (uint64_t)ts.tv_nsec / 1000000ULL);

  if (snap.n_points > 0)
    {
      const struct vg_modbus_point_view *pt = &snap.points[0];

      col = quality_color(pt->quality);

      if (pt->quality == VG_MB_Q_GOOD || pt->quality == VG_MB_Q_STALE)
        {
          if (pt->unit[0] != '\0')
            {
              snprintf(vbuf, sizeof(vbuf), "%.2f%s", (double)pt->value,
                       pt->unit);
            }
          else
            {
              snprintf(vbuf, sizeof(vbuf), "%.2f", (double)pt->value);
            }
        }
      else if (pt->quality == VG_MB_Q_BAD)
        {
          snprintf(vbuf, sizeof(vbuf), "ERR");
        }
      else
        {
          snprintf(vbuf, sizeof(vbuf), "—");
        }

      if (g_acq.value_lbl != NULL)
        {
          lv_label_set_text(g_acq.value_lbl, vbuf);
        }

      if (g_acq.state_lbl != NULL)
        {
          lv_label_set_text(g_acq.state_lbl, quality_text(pt->quality));
          lv_obj_set_style_text_color(g_acq.state_lbl, col, 0);
        }

      if (g_acq.bar != NULL)
        {
          lv_obj_set_style_bg_color(g_acq.bar, col, 0);
        }

      if (g_acq.dot != NULL)
        {
          lv_obj_set_style_bg_color(g_acq.dot, col, 0);
          lv_obj_set_style_border_color(g_acq.dot, col, 0);
        }
    }

  for (i = 0; i < 3; i++)
    {
      if (g_detail_labels[i] == NULL)
        {
          continue;
        }

      if (i < snap.n_points)
        {
          const struct vg_modbus_point_view *pt = &snap.points[i];
          uint32_t age = 0;

          if (pt->last_update_ms != 0 && now_ms >= pt->last_update_ms)
            {
              age = (now_ms - pt->last_update_ms) / 1000u;
            }

          if (pt->quality == VG_MB_Q_GOOD || pt->quality == VG_MB_Q_STALE)
            {
              snprintf(line, sizeof(line),
                       "%s: %.2f%s  %s  %us",
                       pt->label, (double)pt->value,
                       pt->unit, quality_text(pt->quality),
                       (unsigned)age);
            }
          else
            {
              snprintf(line, sizeof(line),
                       "%s: %s  %s",
                       pt->label, quality_text(pt->quality),
                       pt->last_error[0] ? pt->last_error : "—");
            }

          lv_label_set_text(g_detail_labels[i], line);
          lv_obj_set_style_text_color(g_detail_labels[i],
                                      quality_color(pt->quality), 0);
        }
      else
        {
          lv_label_set_text(g_detail_labels[i], "");
        }
    }

  if (g_test_lbl != NULL)
    {
      /* test_result is 96 bytes; keep room for "Test: " prefix. */
      snprintf(tline, sizeof(tline), "Test: %s", snap.test_result);
      lv_label_set_text(g_test_lbl, tline);
    }

  if (g_age_lbl != NULL)
    {
      lv_label_set_text(g_age_lbl,
                        snap.running ? "collector: run" : "collector: stop");
    }
}

